+            }
+
+            this.mMaterial = material;
+        }
+
+        D3D12NativePhongMaterial getNative() {
+            return mMaterial;
+        }
+
+        @Override
+        public void dispose() {
+            if (mMaterial.isValid()) {
+                mMaterial.dispose();
+            }
+        }
+    }
+}

