+// custom assert call that also logs an error message to the logger
+#ifdef DEBUG
+
+#define D3D12NI_ASSERT(x, msg, ...) do { \
+    if (!(x)) \
+    { \
+        D3D12NI_LOG_ERROR(msg, __VA_ARGS__); \
+        assert(0 == msg); \
+    } \
+} while (0)
