+#define D3D12NI_FILL_DEVICE_ERROR(hr, info) \
+do { \
+    _com_error __e(hr); \
+    info.deviceError = hr; \
+    info.deviceErrorReason = ::D3D12::Internal::Utils::ToString(__e.ErrorMessage()); \
+} while (0)
