+     jfloat enabled, jfloat ca, jfloat la, jfloat qa, jfloat isAttenuated, jfloat maxRange,
+     jfloat dirX, jfloat dirY, jfloat dirZ, jfloat innerAngle, jfloat outerAngle, jfloat falloff)
